"""
Iterated suspension: watch a single Z2-map climb the dimensional ladder.

Starting from the identity Z2-map S^0 -> S^0, we repeatedly apply the suspension
functor and confirm that each lift S^k -> S^k is again a valid Z2-map, tracking
the coindex lower bound coind(S^k) >= k that each witness certifies.
"""
from __future__ import annotations
from typing import Callable, List, Tuple

Vertex = Tuple[int, bool]
VertexMap = Callable[[Vertex], Vertex]


def vertices(n: int) -> List[Vertex]:
    return [(i, b) for i in range(n + 1) for b in (True, False)]


def anti(p: Vertex) -> Vertex:
    return (p[0], not p[1])


def is_z2_map(f: VertexMap, m: int) -> bool:
    vs = vertices(m)
    equ = all(f(anti(p)) == anti(f(p)) for p in vs)
    sim = all(not (f(p) == anti(f(q)) and p != anti(q)) for p in vs for q in vs)
    return equ and sim


def susp(f: VertexMap, m: int, n: int) -> VertexMap:
    def g(p: Vertex) -> Vertex:
        i, b = p
        if i == m + 1:
            return (n + 1, b)
        return f((i, b))  # suspV keeps (index, sign)
    return g


def main() -> None:
    f: VertexMap = lambda p: p          # identity on S^0
    m = 0
    print(f"level {m}: coind(S^{m}) >= {m}  valid = {is_z2_map(f, m)}")
    for _ in range(5):
        f = susp(f, m, m)               # S^m -> S^m  becomes  S^(m+1) -> S^(m+1)
        m += 1
        print(f"level {m}: coind(S^{m}) >= {m}  valid = {is_z2_map(f, m)}")


if __name__ == "__main__":
    main()

"""
Existence table of Z2-maps S^m -> S^n via the decidable positive-vertex criterion.

For each pair (m, n) with small m, n we exhaustively search the finite space of
positive-vertex image assignments g : {0..m} -> V(S^n) for one whose induced map
is simplicial.  The resulting Boolean table exhibits the constructive lower bound
(the lower triangle m <= n is filled) and the Borsuk-Ulam obstruction at (1,0)
and (2,1) (no map when m > n).
"""
from __future__ import annotations
from itertools import product
from typing import List, Optional, Tuple

Vertex = Tuple[int, bool]


def vertices(n: int) -> List[Vertex]:
    return [(i, b) for i in range(n + 1) for b in (True, False)]


def anti(p: Vertex) -> Vertex:
    return (p[0], not p[1])


def exists_map(m: int, n: int) -> bool:
    vs_m = vertices(m)
    for combo in product(vertices(n), repeat=m + 1):
        g = list(combo)

        def f(p: Vertex, g=g) -> Vertex:
            i, b = p
            return g[i] if b else anti(g[i])

        if all(not (f(p) == anti(f(q)) and p != anti(q))
               for p in vs_m for q in vs_m):
            return True
    return False


def main() -> None:
    N = 3
    header = "     " + "".join(f" n={n}" for n in range(N))
    print(header)
    for m in range(N):
        row = f" m={m} "
        for n in range(N):
            row += "  Y " if exists_map(m, n) else "  . "
        print(row)
    print("\nY = a Z2-map S^m -> S^n exists;  . = none (obstruction).")


if __name__ == "__main__":
    main()

