function DECIDE-Z2-MAP(m, n):
  for each assignment g : {0..m} -> V(S^n):        # (2(n+1))^(m+1) choices
      define f(i, +) = g[i];  f(i, -) = anti(g[i])
      simplicial <- true
      for each p in V(S^m):
          for each q in V(S^m):
              if f(p) = anti(f(q)) and p != anti(q):
                  simplicial <- false; break
      if simplicial: return g            # witness found
  return NONE                            # no Z2-map exists (obstruction)

