from itertools import product
from typing import Callable, List, Optional, Tuple

Vertex = Tuple[int, bool]


def vertices(n: int) -> List[Vertex]:
    """The 2*(n+1) signed unit vectors +/- e_i of S^n."""
    return [(i, b) for i in range(n + 1) for b in (True, False)]


def anti(p: Vertex) -> Vertex:
    """Antipodal map: flip the sign bit."""
    return (p[0], not p[1])


def decide_z2_map(m: int, n: int) -> Optional[List[Vertex]]:
    """
    Decide whether a Z2-map S^m -> S^n exists, returning positive-vertex data
    witnessing one (or None).  Uses that every equivariant map is determined by
    the images g[i] = f(i, True) of the positive vertices; the negative vertices
    are forced by equivariance, so only simpliciality must be checked.
    """
    verts_m = vertices(m)
    for combo in product(vertices(n), repeat=m + 1):
        g = list(combo)

        def f(p: Vertex, g=g) -> Vertex:
            i, b = p
            return g[i] if b else anti(g[i])

        simplicial = all(
            not (f(p) == anti(f(q)) and p != anti(q))
            for p in verts_m for q in verts_m
        )
        if simplicial:
            return g
    return None

