function IS-ANTIPODAL-LABELLING(m, L):
  return for all p in V(S^m):  L(anti p) = -L(p)

function HAS-COMPLEMENTARY-EDGE(m, L):
  for each p in V(S^m):
      for each q in V(S^m):
          if p != anti(q) and L(p) = -L(q):   # a face with opposite labels
              return true
  return false      # its absence would give a Z2-map S^m -> S^(m-1)

