from itertools import product
from typing import Dict, List, Tuple

Vertex = Tuple[int, bool]


def vertices(n: int) -> List[Vertex]:
    return [(i, b) for i in range(n + 1) for b in (True, False)]


def anti(p: Vertex) -> Vertex:
    return (p[0], not p[1])


def is_antipodal_labelling(m: int, label: Dict[Vertex, int]) -> bool:
    """
    Check the Tucker antipodal condition L(anti p) = -L(p) for a labelling
    L : V(S^m) -> {+/-1, ..., +/-m} of the cross-polytope sphere.  Tucker's lemma
    states that any such antipodal labelling must contain a 'complementary edge':
    an actual edge {p, q} of S^m (a non-antipodal pair) with L(p) = -L(q).  The
    absence of such an edge is exactly what a Z2-map S^m -> S^(m-1) would provide,
    which is why Tucker's lemma yields the Borsuk-Ulam obstruction.
    """
    return all(label[anti(p)] == -label[p] for p in vertices(m))


def has_complementary_edge(m: int, label: Dict[Vertex, int]) -> bool:
    """Search for a non-antipodal pair p, q with L(p) = -L(q) (a face of S^m)."""
    vs = vertices(m)
    for p in vs:
        for q in vs:
            if p != anti(q) and label[p] == -label[q]:
                return True
    return False

