"""Heatmap of Z2-map existence over dimensions (m, n)."""
from itertools import product
from typing import List, Tuple

import matplotlib.pyplot as plt
import numpy as np

Vertex = Tuple[int, bool]


def vertices(n: int) -> List[Vertex]:
    return [(i, b) for i in range(n + 1) for b in (True, False)]


def anti(p: Vertex) -> Vertex:
    return (p[0], not p[1])


def exists_map(m: int, n: int) -> bool:
    vs = vertices(m)
    for combo in product(vertices(n), repeat=m + 1):
        g = list(combo)
        f = lambda p, g=g: g[p[0]] if p[1] else anti(g[p[0]])
        if all(not (f(p) == anti(f(q)) and p != anti(q)) for p in vs for q in vs):
            return True
    return False


def main() -> None:
    N = 4
    grid = np.zeros((N, N))
    for m in range(N):
        for n in range(N):
            grid[m, n] = 1.0 if exists_map(m, n) else 0.0
    fig, ax = plt.subplots(figsize=(5, 5))
    ax.imshow(grid, origin="lower", cmap="Greens", vmin=0, vmax=1)
    for m in range(N):
        for n in range(N):
            ax.text(n, m, "Y" if grid[m, n] else "-", ha="center", va="center")
    ax.set_xlabel("n  (target S^n)")
    ax.set_ylabel("m  (source S^m)")
    ax.set_title("Existence of a Z2-map S^m -> S^n")
    ax.set_xticks(range(N)); ax.set_yticks(range(N))
    plt.tight_layout()
    plt.savefig("existence_heatmap.png", dpi=150)
    print("wrote existence_heatmap.png")


if __name__ == "__main__":
    main()

"""Draw the cross-polytope spheres S^1 (diamond) and S^2 (octahedron)."""
import matplotlib.pyplot as plt
from mpl_toolkits.mplot3d import Axes3D  # noqa: F401


def draw_S1(ax) -> None:
    pts = {"+e0": (1, 0), "-e0": (-1, 0), "+e1": (0, 1), "-e1": (0, -1)}
    edges = [("+e0", "+e1"), ("+e1", "-e0"), ("-e0", "-e1"), ("-e1", "+e0")]
    for a, b in edges:
        xa, ya = pts[a]; xb, yb = pts[b]
        ax.plot([xa, xb], [ya, yb], "b-")
    for name, (x, y) in pts.items():
        ax.plot(x, y, "ko"); ax.text(x * 1.15, y * 1.15, name, ha="center")
    ax.set_title("S^1 = boundary of 2-cross-polytope")
    ax.set_aspect("equal"); ax.axis("off")


def draw_S2(ax) -> None:
    verts = {"+e0": (1, 0, 0), "-e0": (-1, 0, 0), "+e1": (0, 1, 0),
             "-e1": (0, -1, 0), "+e2": (0, 0, 1), "-e2": (0, 0, -1)}
    names = list(verts)
    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            a, b = names[i], names[j]
            if a[1:] == b[1:]:   # skip antipodal pairs (not edges)
                continue
            xa = verts[a]; xb = verts[b]
            ax.plot([xa[0], xb[0]], [xa[1], xb[1]], [xa[2], xb[2]], "b-", alpha=0.4)
    for name, (x, y, z) in verts.items():
        ax.scatter(x, y, z, c="k"); ax.text(x, y, z, name)
    ax.set_title("S^2 = octahedron (3-cross-polytope boundary)")


def main() -> None:
    fig = plt.figure(figsize=(10, 5))
    ax1 = fig.add_subplot(1, 2, 1)
    ax2 = fig.add_subplot(1, 2, 2, projection="3d")
    draw_S1(ax1); draw_S2(ax2)
    plt.tight_layout()
    plt.savefig("crosspolytope_spheres.png", dpi=150)
    print("wrote crosspolytope_spheres.png")


if __name__ == "__main__":
    main()
